(function(root){'use strict';const App=root.MT_WORKSPACE_APP;
const tasks=[['Plan a passage','tid reise fart distanse voyage time distance speed eta','index.html?page=voyage-estimate','Distance, sea time and route scenarios'],['Estimate fuel and delivery volume','bunkers fuel drivstoff diesel density tetthet consumption forbruk','workspace.html#workflow?task=fuelNeed','Fuel requirement → delivery volume → entered price'],['Fill a tank','tank fylle flow volumstrøm pumpe filling','workspace.html#workflow?task=fillTime','Required volume and delivery flow'],['Calculate hydraulic power','hydraulikk trykk pressure hydraulic power effekt','workspace.html#workflow?task=hydraulicPower','Pressure difference, flow and efficiency'],['Inspect a structural load','bjelke last stress kraft beam force bending','students/interactive.html#beam','Support reactions, bending and deflection'],['Check a circuit','strøm spenning resistor motor electrical krets','students/interactive.html#resistor-network','Kirchhoff circuit and virtual measurements'],['Practice for a test','eksamen prøve test øving oppgaver practice exam','workspace.html#tests','Weighted and timed self-tests'],['Find a relationship','formel ukjent formula known unknown symbol','workspace.html#formulas','Required values, relations and model conditions'],['Compare experiments','compare sammenlign sensitivity følsomhet model','workspace.html#analysis','A/B curves, numerical differences and two-input maps'],['Prepare a lesson','undervisning lærer teacher class lesson','workspace.html#teach','Teaching packs, class assignments and Moodle export'],['Keep or move your work','lagre backup eksport prosjekt rapport data','workspace.html#data','Selected backups and reviewed restore']];
const glossary=[['Displacement','Deplasement','Mass of water displaced; equal to vessel mass in static equilibrium.'],['Draft','Dypgang','Vertical distance from the waterline to the stated keel reference.'],['Trim','Trim','Difference between aft and forward draft, with the sign convention stated by the tool.'],['Heel','Krengning','Transverse inclination about the longitudinal axis.'],['Righting arm','Rettende arm','Perpendicular lever between gravity and buoyancy force lines.'],['Free surface','Fri væskeoverflate','Liquid surface that can shift and reduce initial stability.'],['Mass moment','Massemoment','Mass times distance, for example t·m; distinct from force moment.'],['Torque','Dreiemoment','Force moment about a rotation axis, measured in N·m.'],['Pressure difference','Trykkforskjell','Difference of two pressures on the same reference.'],['Absolute pressure','Absolutt trykk','Pressure relative to vacuum; distinguish it from gauge pressure.'],['Volume flow','Volumstrøm','Volume passing per unit time.'],['Mass flow','Massestrøm','Mass passing per unit time.'],['Enthalpy','Entalpi','Specific enthalpy h is an energy quantity per mass.'],['Entropy','Entropi','Specific entropy s uses an energy-per-mass-per-temperature unit.'],['Vapour quality','Dampkvalitet','Vapour mass fraction in a saturated two-phase mixture.'],['Efficiency','Virkningsgrad','Useful output divided by the defined input.'],['Slip','Sakking','Relative difference between synchronous speed and rotor speed.'],['Power factor','Effektfaktor','Active power divided by apparent power for the stated system.'],['Bearing','Peiling','Angular direction from a stated north/reference convention.'],['Current set','Strømretning','Direction towards which the current flows.'],['Uncertainty','Usikkerhet','Quantified uncertainty under the stated measurement model.'],['Sensitivity','Følsomhet','Change in a result with respect to an input near a stated baseline.'],['Scenario','Scenario','A saved combination of inputs, assumptions and resulting values.'],['Provenance','Datagrunnlag','The saved origin, unit and version associated with a value.']];
function help(c){return {html:'<h1>Find tools & get help</h1><section class="panel"><h2>What are you trying to do?</h2><label>Search by task<input id="task-query" type="search" placeholder="fill a tank, estimate fuel, prepare a lesson…"></label><div id="task-results"></div></section><section class="panel"><h2>Guided walkthroughs</h2><p>Choose a walkthrough to highlight the actual controls. You remain in control of every input and saved action.</p><div class="next-actions"><button id="tour-learning">Practice a question</button><button id="tour-project">Save a project</button><button id="tour-backup">Back up your work</button></div></section><section class="panel" id="offline-section"><h2>Download Education chapters</h2><fieldset><legend>Include these chapters</legend>'+c.manifest.chapters.map(v=>'<label class="check"><input name="offline-chapter" type="checkbox" value="'+v.number+'">'+v.number+' · '+c.esc(v.title)+'</label>').join('')+'</fieldset><button id="offline-build">Build chapter ZIP</button><p id="offline-status" role="status"></p></section><section class="panel"><h2>Shared terminology</h2><p>English and Norwegian terms refer to the same defined quantities. Numerical model conditions and scientific notation retain their stated meanings.</p><label>Find a term<input id="glossary-query" type="search"></label><div id="glossary-results"></div></section><section class="panel"><h2>Report a problem</h2><p>Prepare a local report for review. You choose whether to include diagnostic context; nothing is sent automatically.</p><form id="issue-form"><label>What happened?<textarea id="issue-description" maxlength="5000" required></textarea></label><label>Expected result<textarea id="issue-expected" maxlength="3000"></textarea></label><label class="check"><input id="issue-context" type="checkbox">Include page path, selected chapter/model and browser language</label><label class="check"><input id="issue-values" type="checkbox">Include values I enter below</label><label>Optional calculation values<textarea id="issue-inputs" maxlength="10000" disabled></textarea></label><button>Prepare report for review</button></form><pre id="issue-preview" hidden></pre><button id="issue-download" disabled>Download reviewed report</button><a href="mailto:contact@marinetools.app">Open support email →</a></section>',bind(){function search(){const q=c.$('task-query').value.toLowerCase().trim().split(/\s+/).filter(Boolean),hits=tasks.map(t=>({t,score:q.filter(word=>(t[0]+' '+t[1]+' '+t[3]).toLowerCase().includes(word)).length})).filter(v=>!q.length||v.score).sort((a,b)=>b.score-a.score);c.$('task-results').innerHTML=hits.map(({t})=>'<article class="next-step"><h3><a href="'+t[2]+'">'+c.esc(t[0])+' →</a></h3><p>'+c.esc(t[3])+'</p></article>').join('')||c.empty('No matching task. Try a quantity, tool name or Norwegian term.');}function terms(){const q=c.$('glossary-query').value.toLowerCase();c.$('glossary-results').innerHTML=c.table(['English','Norsk bokmål','Meaning'],glossary.filter(r=>r.join(' ').toLowerCase().includes(q)));}c.on('task-query','input',search);c.on('glossary-query','input',terms);search();terms();c.button('offline-build',async()=>{const chosen=[...document.querySelectorAll('[name=offline-chapter]:checked')].map(n=>Number(n.value));if(!chosen.length)throw Error('Choose at least one chapter.');await c.load('workspace-offline-20261030.js');c.$('offline-build').disabled=true;try{const blob=await root.MT_OFFLINE.build(c,chosen,text=>c.$('offline-status').textContent=text),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MarineTools-Education-chapters-'+chosen.join('-')+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);c.$('offline-status').textContent='Chapter package prepared. Extract all files before opening index.html.';}finally{c.$('offline-build').disabled=false;}});let report=null;c.on('issue-values','change',()=>{c.$('issue-inputs').disabled=!c.$('issue-values').checked;report=null;c.$('issue-download').disabled=true;});c.on('issue-form','input',()=>{report=null;c.$('issue-download').disabled=true;});c.on('issue-form','submit',e=>{e.preventDefault();report={format:'marine-tools-issue',version:1,build:'2026-10-30-next',description:c.$('issue-description').value,expected:c.$('issue-expected').value};if(c.$('issue-context').checked)report.context={path:location.pathname,view:c.view,chapter:c.params.get('chapter'),model:c.params.get('model'),question:c.params.get('question'),language:navigator.language};if(c.$('issue-values').checked)report.enteredValues=c.$('issue-inputs').value;c.$('issue-preview').textContent=JSON.stringify(report,null,2);c.$('issue-preview').hidden=false;c.$('issue-download').disabled=false;});c.button('issue-download',()=>{if(!report)throw Error('Review a report first.');c.download('MarineTools-issue-report.json',JSON.stringify(report,null,2));});for(const [id,tour]of [['tour-learning','practice'],['tour-project','projects'],['tour-backup','data']])c.button(id,()=>startTour(c,tour));}};}
let tourCleanup=null;
function startTour(c,view){tourCleanup?.();const stages={practice:[['#practice-prompt','Read the question and identify its units.'],['#practice-answer','Enter your own answer. The walkthrough does not fill or submit it.'],['#next-practice-form button[type=submit]','Check your answer and review the feedback.']],projects:[['#project-title','Name a real project you want to keep.'],['#project-vessel','Attach a saved vessel profile when relevant.'],['#project-create button','Create it when ready, then save calculations from an experiment.']],data:[['[name=backup-group]','Select which records to include.'],['#backup-download','Download a portable backup.'],['#backup-file','Review a backup file before restoring selected groups.']] }[view];let i=0,box=null;const onRender=()=>{if(root.MT_WORKSPACE_APP.context().view===view)show();};function stop(){document.removeEventListener('mt-workspace-render',onRender);document.removeEventListener('keydown',key);document.querySelectorAll('.tour-target').forEach(n=>n.classList.remove('tour-target'));box?.remove();tourCleanup=null;}function key(e){if(e.key==='Escape')stop();}function show(){box?.remove();document.querySelectorAll('.tour-target').forEach(n=>n.classList.remove('tour-target'));const target=document.querySelector(stages[i][0]);if(!target){stop();c.error(Error('This walkthrough step is unavailable in the current view.'));return;}target.classList.add('tour-target');target.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});box=document.createElement('section');box.className='next-tour';box.setAttribute('role','dialog');box.setAttribute('aria-modal','false');box.setAttribute('aria-label','Guided walkthrough');box.innerHTML='<p>Step '+(i+1)+' / '+stages.length+'</p><p>'+c.esc(stages[i][1])+'</p><div class="next-actions"><button id="tour-prev"'+(i===0?' disabled':'')+'>Previous</button><button id="tour-next">'+(i===stages.length-1?'Finish':'Next')+'</button><button id="tour-close">Close walkthrough</button></div>';document.body.append(box);box.querySelector('#tour-prev').onclick=()=>{i--;show();};box.querySelector('#tour-next').onclick=()=>{if(i===stages.length-1)stop();else{i++;show();}};box.querySelector('#tour-close').onclick=stop;box.querySelector('#tour-next').focus();}tourCleanup=stop;document.addEventListener('keydown',key);document.addEventListener('mt-workspace-render',onRender);location.hash=view;if(c.view===view)show();}
root.MT_WORKSPACE_HELP={tasks,glossary};App.register({help});
})(window);
